// Some portions generated by Co-Pilot
import { fireEvent, render, screen, within } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import PlatformBreakdown from "../index";
import type {
  PlatformBreakdownRow as Row,
  PlatformBreakdownStats,
} from "@/utils/fetchPlatformBreakdown";

vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useTranslations: (namespace: "ModernPages.stats" | "ModernPages.common") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

vi.mock("@/components/Dashboard/PieChart", () => ({
  default: ({
    name,
    data,
    onPointClick,
  }: {
    name: string;
    data: Array<{ id: string; name: string; y: number; visible: boolean }>;
    onPointClick: (point: { id: string; name: string }) => void;
  }) => (
    <figure aria-label={name}>
      {data.map((point) => (
        <button
          key={point.id}
          aria-pressed={!point.visible}
          data-count={point.y}
          onClick={() => onPointClick(point)}
        >
          {point.name}
        </button>
      ))}
    </figure>
  ),
}));

const row = (
  version: number,
  os: string,
  architecture: string,
  imageType: string,
  archive: number,
  installer = 0,
): Row => ({ version, os, architecture, imageType, archive, installer });

const stats: PlatformBreakdownStats = {
  rows: [
    row(17, "linux", "x64", "jdk", 6),
    row(17, "linux", "aarch64", "jre", 4),
    row(17, "mac", "aarch64", "jdk", 5),
    row(17, "aix", "ppc64", "sbom", 1),
    row(21, "windows", "x64", "jdk", 1, 3),
    row(21, "linux", "x64", "debugimage", 2),
  ],
};

const chart = (name: string) =>
  Object.fromEntries(
    within(screen.getByRole("figure", { name }))
      .queryAllByRole("button")
      .map((button) => [
        button.textContent,
        Number(button.getAttribute("data-count")),
      ]),
  );

const point = (name: string, slice: string) =>
  within(screen.getByRole("figure", { name })).getByRole("button", {
    name: slice,
  });

const click = (name: string, slice: string) =>
  fireEvent.click(point(name, slice));

describe("PlatformBreakdown", () => {
  it("shows labelled breakdowns across all versions", () => {
    render(<PlatformBreakdown stats={stats} />);
    expect(chart("Operating system")).toEqual({
      Linux: 12,
      macOS: 5,
      Windows: 4,
      AIX: 1,
    });
    expect(chart("Image type")).toEqual({ JDK: 15, JRE: 4, Other: 3 });
    expect(chart("Package type")).toEqual({ Archive: 19, Installer: 3 });
  });

  it("excludes a slice from the other charts and combines different filters", () => {
    render(<PlatformBreakdown stats={stats} />);
    click("Operating system", "Linux");

    expect(point("Operating system", "Linux")).toHaveAttribute(
      "aria-pressed",
      "true",
    );
    expect(chart("Architecture")).toEqual({ x64: 4, aarch64: 5, ppc64: 1 });
    expect(chart("Image type")).toEqual({ JDK: 9, Other: 1 });
    expect(chart("Package type")).toEqual({ Archive: 7, Installer: 3 });

    click("Image type", "JDK");
    expect(chart("Operating system")).toEqual({ Linux: 6, AIX: 1 });
    expect(chart("Architecture")).toEqual({ ppc64: 1 });
    expect(chart("Package type")).toEqual({ Archive: 1 });
  });

  it("excludes Solaris rather than retaining only its architectures", () => {
    render(
      <PlatformBreakdown
        stats={{
          rows: [
            row(17, "linux", "x64", "jdk", 100),
            row(17, "linux", "aarch64", "jdk", 20),
            row(17, "solaris", "sparcv9", "jdk", 7),
            row(17, "solaris", "x64", "jre", 2),
            row(21, "windows", "x64", "jdk", 8, 5),
          ],
        }}
      />,
    );
    expect(chart("Architecture")).toEqual({
      x64: 115,
      aarch64: 20,
      sparcv9: 7,
    });
    click("Operating system", "Solaris");
    expect(chart("Architecture")).toEqual({ x64: 113, aarch64: 20 });
    click("Operating system", "Solaris");
    expect(chart("Architecture")).toEqual({
      x64: 115,
      aarch64: 20,
      sparcv9: 7,
    });
  });

  it("supports multiple exclusions in one chart and restores them", () => {
    render(<PlatformBreakdown stats={stats} />);
    click("Operating system", "Linux");
    click("Operating system", "macOS");
    expect(chart("Architecture")).toEqual({ x64: 4, ppc64: 1 });
    click("Operating system", "Windows");
    click("Operating system", "AIX");
    expect(chart("Architecture")).toEqual({});
    click("Operating system", "Linux");
    expect(chart("Architecture")).toEqual({ x64: 8, aarch64: 4 });
    fireEvent.click(screen.getByRole("button", { name: "Clear filters" }));
    expect(chart("Architecture")).toEqual({ x64: 12, aarch64: 9, ppc64: 1 });
    expect(screen.queryByRole("button", { name: "Clear filters" })).toBeNull();
  });

  it("subtracts excluded package types from the other charts", () => {
    render(<PlatformBreakdown stats={stats} />);
    click("Package type", "Archive");
    expect(chart("Operating system")).toEqual({ Windows: 3 });
    expect(chart("Architecture")).toEqual({ x64: 3 });
    expect(chart("Package type")).toEqual({ Archive: 19, Installer: 3 });
    click("Package type", "Installer");
    expect(chart("Operating system")).toEqual({});
    click("Package type", "Archive");
    expect(chart("Operating system")).toEqual({
      Linux: 12,
      macOS: 5,
      Windows: 1,
      AIX: 1,
    });
  });

  it("excludes all image types grouped as Other", () => {
    render(<PlatformBreakdown stats={stats} />);
    click("Image type", "Other");
    expect(chart("Operating system")).toEqual({
      Linux: 10,
      macOS: 5,
      Windows: 4,
    });
    expect(chart("Package type")).toEqual({ Archive: 16, Installer: 3 });
  });

  it("keeps excluded items available when changing JDK version", () => {
    render(<PlatformBreakdown stats={stats} />);
    click("Image type", "JRE");
    fireEvent.change(screen.getByRole("combobox", { name: "JDK version" }), {
      target: { value: "21" },
    });
    expect(chart("Operating system")).toEqual({ Windows: 4, Linux: 2 });
    expect(chart("Image type")).toEqual({ JDK: 4, Other: 2, JRE: 0 });
    expect(point("Image type", "JRE")).toHaveAttribute("aria-pressed", "true");
    click("Image type", "JRE");
    expect(screen.queryByRole("button", { name: "Clear filters" })).toBeNull();
    expect(chart("Package type")).toEqual({ Archive: 3, Installer: 3 });
  });
});
